                    "h": 5
                  },
                  "type": "vis",
                  "config": {
                    "type": "metric",
                    "data_source": {
                      "type": "data_view_spec",
                      "index_pattern": "kibana_sample_data_logs",
                      "time_field": "timestamp"
                    },
                    "metrics": [
                      {
                        "type": "primary",
                        "operation": "average",
                        "field": "bytes"
                      }
                    ]
                  }
                },
                {
                  "grid": {
                    "x": 24,
                    "y": 5,
                    "w": 24,
                    "h": 10
